Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_update_non_head_all_times_non_zero(void) {
    // Setup: Build a linked list with at least two nodes.
    // We need the target node NOT to be the head.
    // Path conditions: ct != 0, wt != 0, tat != 0.
    // The loop must execute (ptr != NULL && ptr->ID != id) and then exit when found.
    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;
    node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial state of node with ID 3 (non-head, third node).
    node *ptr = root;
    while (ptr != NULL && ptr->ID != 3) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Test: Update node with ID 3 (non-head) with all non-zero times.
    int new_ct = 10;
    int new_wt = 5;
    int new_tat = 8;
    update(&root, 3, new_ct, new_wt, new_tat);

    // Assertions: Verify the target node's fields are updated.
    ptr = root;
    while (ptr != NULL && ptr->ID != 3) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(new_ct, ptr->CT);
    TEST_ASSERT_EQUAL_INT(new_wt, ptr->WT);
    TEST_ASSERT_EQUAL_INT(new_tat, ptr->TAT);

    // Verify other nodes are unchanged.
    ptr = root;
    TEST_ASSERT_EQUAL_INT(1, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);
    ptr = ptr->next;
    TEST_ASSERT_EQUAL_INT(2, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Cleanup
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}

